/bin/zsh -lc "git diff --stat
git diff --check
node --input-type=module <<'NODE'
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import assert from 'node:assert/strict';
import { sentences } from './server/lib/counterCardLint.js';
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json'));
const before = JSON.parse(execFileSync('git', ['show', 'c24aea0:server/kristy_perimeter_kb.json'], { maxBuffer: 64 << 20 }));
const head = JSON.parse(execFileSync('git', ['show', 'HEAD:server/kristy_perimeter_kb.json'], { maxBuffer: 64 << 20 }));
const text = readFileSync('server/test/acceptance/twoLinePin.js', 'utf8');
const parsePins = s => JSON.parse(s.slice(s.indexOf('export const TWO_LINE = ') + 'export const TWO_LINE = '.length, s.indexOf('\\n};') + 2));
const pins = parsePins(text);
const oldPins = parsePins(execFileSync('git', ['show', 'HEAD:server/test/acceptance/twoLinePin.js'], { maxBuffer: 64 << 20 }).toString());
const counts = { label_nonGMO_vs_organic: [3, 5, 2], cooking_oils: [2, 1, 2], sugars: [2, 1, 2], soy_milk: [2, 1, 2], tortilla_chips: [2, 1, 2], tortillas: [2, 1, 2], popcorn: [1, 1, 1] };
const appendedFields = ['buying_tips', 'watch_out', 'sources'];
let maxWords = 0;
assert.equal(kb.entries.length, head.entries.length);
for (const card of kb.entries) {
 const id = card.id;
 const original = before.entries.find(e => e.id === id);
 if ("'!counts[id]) {
  assert.deepEqual(card, head.entries.find(e => e.id === id), `untargeted card ${id}`);
  continue;
 }
 for (const [i, field] of appendedFields.entries()) {
  assert.equal(card[field].length, original[field].length + counts[id][i], `${id}.${field} append count`);
  assert.deepEqual(card[field].slice(0, original[field].length), original[field], `${id}.${field} prefix`);
 }
 const strip = e => Object.fromEntries(Object.entries(e).filter(([k]) => !appendedFields.includes(k)));
 assert.deepEqual(strip(card), strip(original), `${id} all frozen fields`);
 for (const field of ['"'decision', ...appendedFields]) assert.deepEqual(pins[id][field], card[field], "'`${id}.${field} pin`);
 for (const [field, value] of Object.entries(oldPins[id])) {
  if (!appendedFields.includes(field)) assert.deepEqual(pins[id][field], value, `${id}.${field} additional pin preserved`);
 }
 for (const field of ['"'buying_tips', 'watch_out']) {
  for (const line of card[field].slice(original[field].length)) {
   for (const sentence of sentences(line)) {
    const words = sentence.split(/\\s+/).length;
    maxWords = Math.max(maxWords, words);
    assert.ok(words <= 20, "'`${id} sentence too long`);
    assert.ok((sentence.match(/;/g) || []).length <= 1);
   }
  }
 }
 console.log(`${id}: +${counts[id].join('"'/')} tips/watch_out/sources; prefixes, frozen fields and pins preserved"'`);
}
for (const id of Object.keys(oldPins)) {
 if (!counts[id]) assert.deepEqual(pins[id], oldPins[id], `untargeted pin ${id}`);
}
assert.equal(Object.keys(pins).length, Object.keys(oldPins).length);
for (const file of ['"'docs/do-lines-review.md', 'server/lib/doLines.json']) {
 assert.equal(readFileSync(file, 'utf8'), execFileSync('git', ['show', "'`HEAD:${file}`]).toString(), `${file} unchanged`);
}
console.log(`All append counts match; maximum new sentence: ${maxWords} words; do-line files unchanged.`);
NODE'

